'use strict';
const M=window.LabMath, $=s=>document.querySelector(s), f=(x,n=2)=>Number(x).toFixed(n), pct=x=>x===null?'undefined':f(100*x,1)+'%';
const qa=(q,a)=>`<details class="question"><summary>${q}</summary><p class="key-answer">${a}</p></details>`;
const note=s=>`<div class="note">${s}</div>`;
const source=(url,title)=>`<p class="source">Optional online reference: <a href="${url}" target="_blank" rel="noopener">${title} ↗</a></p>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const panel=(title,body)=>`<section class="panel"><h3>${title}</h3>${body}</section>`;
const link=(id,title,desc)=>`<a class="tile" href="#${id}"><strong>${title}</strong><small>${desc}</small></a>`;
const badge=s=>`<span class="pill">${s}</span>`;
const scenes=[];
function add(id,block,title,subtitle,html,init){scenes.push({id,block,title,subtitle,html,init});}
function chartFrame(content,xlabel,ylabel,xmax=12,ymax=50){let grid='';for(let i=0;i<=5;i++){const y=280-i*46;grid+=`<line class="gridline" x1="65" x2="590" y1="${y}" y2="${y}"/><text x="53" y="${y+5}" text-anchor="end">${f(ymax*i/5,0)}</text>`;}for(let i=0;i<=4;i++)grid+=`<text x="${65+i*131.25}" y="303" text-anchor="middle">${f(xmax*i/4,1)}</text>`;return `<svg class="chart" viewBox="0 0 640 350" role="img" aria-label="${ylabel} versus ${xlabel}"><text class="label" x="65" y="23">${ylabel}</text>${grid}${content}<text class="label" x="325" y="335" text-anchor="middle">${xlabel}</text></svg>`;}
const point=(x,y,cl='point',text='')=>`<circle class="${cl}" cx="${x}" cy="${y}" r="5"><title>${text}</title></circle>`;
function scatter(rows,xmax,ymax,cl='point'){return rows.map(r=>cl==='validation'?`<path class="validation" d="M${65+r[0]/xmax*525},${280-r[1]/ymax*230-6} l6,6 l-6,6 l-6,-6z"><title>${r[0]}, ${r[1]}</title></path>`:point(65+r[0]/xmax*525,280-r[1]/ymax*230,cl,`${r[0]}, ${r[1]}`)).join('');}
function curve(fn,xmax,ymax){return `<path class="curve" d="${Array.from({length:181},(_,i)=>{const x=xmax*i/180;return `${i?'L':'M'}${65+x/xmax*525},${280-fn(x)/ymax*230}`;}).join(' ')}"/>`;}

add('start',1,'Choose with <em>evidence.</em>','Seven model families. One path from a question to a justified choice.',()=>`
<div class="catalog-opening"><div class="catalog-opening-copy"><p class="eyebrow">MACHINE LEARNING · THE MODEL CATALOGUE</p><h1>Which model<br>fits <em>this problem?</em></h1><p class="lede">Choose a model. Compare it fairly.<br>Explain its result and its limits.</p><div class="opening-routes"><a class="opening-primary" href="#question">Start the lesson ↗</a><a href="#catalogue">Explore the models ↗</a></div></div>
<div class="catalog-opening-art"><svg viewBox="0 0 600 460" role="img" aria-label="Illustrative decision tree: a case follows a sequence of splits to an output."><g class="opening-tree"><path d="M70 230L210 140L365 80H520M210 140L365 190H520M70 230L210 320L365 280H520M210 320L365 390H520"/><g class="opening-nodes"><circle cx="70" cy="230" r="11"/><circle cx="210" cy="140" r="9"/><circle cx="210" cy="320" r="9"/><circle cx="365" cy="80" r="7"/><circle cx="365" cy="190" r="7"/><circle cx="365" cy="280" r="7"/><circle cx="365" cy="390" r="7"/><circle cx="520" cy="80" r="11"/><circle cx="520" cy="190" r="11"/><circle cx="520" cy="280" r="11"/><circle cx="520" cy="390" r="11"/></g></g><g class="opening-paths"><path d="M70 230L210 140L365 80H520"/><path d="M70 230L210 320L365 280H520"/><path d="M70 230L210 140L365 190H520"/></g></svg></div></div>`);
add('question',1,'The question comes <em>before the model.</em>','One row must represent one clear unit. Inputs must exist when you make the prediction.',()=>`
${ModelVisuals.miniControls()}<div class="grid three task-triptych">${panel('A quantity',`<p>One delivery. Distance known at dispatch. Target: travel time in minutes.</p><p class="big">Regression</p>${ModelVisuals.mini("quantity")}<p class="small">Possible candidates: linear regression, kNN, a tree or an ensemble.</p>`)}${panel('A category',`<p>One booking. Information known when booked. Target: missed visit, yes or no.</p><p class="big">Classification</p>${ModelVisuals.mini("category")}<p class="small">Possible candidates: logistic regression, kNN, a tree or an ensemble.</p>`)}${panel('Groups',`<p>One customer. Purchase totals from a fixed past month. No known group label.</p><p class="big">Clustering</p>${ModelVisuals.mini("groups")}<p class="small">K-means is one candidate if distance and group shape make sense.</p>`)}</div>
${note('A <b>target</b> is the answer we want to predict. A <b>feature</b> is an input. A customer ID is usually an identifier, not a useful measurement of similarity.')}
${qa('Can arrival time be an input when we predict delivery duration at dispatch?','No. Arrival time is not available yet. It also reveals the answer. That would be leakage: information from outside the valid training or prediction boundary.')}`,($,root)=>ModelVisuals.mountMini(root));
add('purpose',1,'Description, prediction, <em>cause.</em>','These questions need different kinds of evidence.',()=>`
<div class="grid three">${panel('Describe','<p>“Last month, longer routes had longer travel times.”</p><p>This summarizes the observed data.</p>')}${panel('Predict','<p>“This new route may take 26 minutes.”</p><p>This needs evaluation on relevant cases not used to fit the rule.</p>')}${panel('Explain a cause','<p>“Will changing this policy reduce travel time?”</p><p>A prediction alone does not identify the effect of an intervention.</p>')}</div>
<div class="grid" style="margin-top:24px">${panel('A simple reference','<p>A <b>baseline</b> is a simple prediction rule. Example: always predict a value learned from training, or always predict the most common class.</p><p>Its score tells us whether added model complexity is useful.</p>')}${panel('The data boundary','<p>A sample that looks like the full file may still miss people, places or dates from the population we care about.</p><p>Similarity to the file is not proof of population representativeness.</p>')}</div>
${qa('A complex model beats a weak baseline. Is it ready to use?','Not necessarily. Check the baseline, validation design, error costs, population, uncertainty and operational limits. A/B testing needs its own treatment; it is not covered by this catalogue.')}`);
add('learn-configure',2,'01 · Learn <em>a rule.</em>','Fit uses known inputs and known answers. Follow the rows into a fitted rule.',()=>ModelVisuals.html('fit-process'),($,root)=>ModelVisuals.mount('fit-process',root));
add('apply-rule',2,'02 · Apply <em>the same rule.</em>','Predict uses the saved rule with a new input. The answer is not supplied.',()=>ModelVisuals.html('predict-process'),($,root)=>ModelVisuals.mount('predict-process',root));
add('learning-terms',2,'Values learned <em>from training.</em>','A model learns a rule. Data preparation also learns values from the training rows.',()=>`
${ModelVisuals.miniControls()}<div class="learning-terms term-pair"><section class="term-card"><h3>Learned parameter</h3><p class="term-definition">A value the fitting rule learns from training data.</p>${ModelVisuals.mini("learned")} <dl><dt>Example</dt><dd>Slope = 2 min/km, or split at 7 days</dd><dt>Where it comes from</dt><dd>Training data and fitting rule</dd></dl></section><section class="term-card"><h3>Preprocessing parameter</h3><p class="term-definition">A value learned during data preparation, before the model uses the data.</p>${ModelVisuals.mini("prep")} <dl><dt>Example</dt><dd>Training mean used to scale a column</dd><dt>Where it comes from</dt><dd>Only the training portion of the current fit</dd></dl></section></div>`,($,root)=>ModelVisuals.mountMini(root));
add('chosen-settings',2,'Settings <em>we choose.</em>','Choose settings with validation. A decision threshold also depends on the cost of each error.',()=>`
${ModelVisuals.miniControls()}<div class="learning-terms term-pair"><section class="term-card"><h3>Hyperparameter</h3><p class="term-definition">A setting chosen before a fit; validation helps select it.</p>${ModelVisuals.mini("hyper")} <dl><dt>Example</dt><dd>k = 3 neighbours; maximum tree depth = 4</dd><dt>Where it comes from</dt><dd>Chosen configuration; select with validation</dd></dl></section><section class="term-card"><h3>Decision threshold</h3><p class="term-definition">A cutoff that turns a predicted probability into a decision.</p>${ModelVisuals.mini("threshold")} <dl><dt>Example</dt><dd>Flag when probability ≥ 0.6</dd><dt>Where it comes from</dt><dd>Use case and validation; not a fitted coefficient</dd></dl></section></div>
${qa('Does a model with more settings necessarily solve the problem better?','No. Complexity, data quality and validation quality are separate. More flexibility cannot repair missing information or leakage. Check generalization: performance on relevant new cases.')}`,($,root)=>ModelVisuals.mountMini(root));
add('complexity',2,'Fit the detail.<br><em>Check the new cases.</em>','Live kNN regression on invented deliveries. Each row is a trip; x = distance (km), y = duration (min).',()=>`
<div class="toolbar"><label for="k">Neighbours k <input id="k" type="range" min="1" max="12" value="3"><output id="k-value">3</output></label><label for="knn-query">New distance (km) <input id="knn-query" type="range" min="1" max="12" step="0.1" value="6.5"><output id="knn-query-value">6.5</output></label><button id="knn-sweep">Move the new trip</button><button id="reset-knn">Reset</button>${badge('Live calculation')}</div>
<div class="grid wide"><section class="panel"><div id="knn-chart"></div><div class="legend"><span>● Cyan circles: 12 training trips</span><span>◆ Amber diamonds: 6 validation trips</span><span>Green line: prediction</span></div></section><section class="panel"><h3>Follow the nearest inputs</h3><p>Move the new trip. Its nearest distances select the known durations to average. Change k to consult more or fewer trips.</p><p id="knn-working" class="formula"></p><div id="knn-metrics"></div><p class="small result">Small k can follow noise. Large k can smooth away useful structure. Training error alone cannot choose the model.</p></section></div>
${qa('Why can k = 1 reproduce training durations exactly?','A training row can select itself. That explains its zero training error here. Validation trips have different distances and do not get their own answers as inputs.')}
<details><summary>Read all rows and the tie rule</summary>${table(['Role','(km, min)'],[['Training',M.training.map(r=>`(${r.join(', ')})`).join('; ')],['Validation',M.validation.map(r=>`(${r.join(', ')})`).join('; ')]])}<p class="small">Equal distances use the earlier training row first. These 18 cases are synthetic, not measured transport data. Validation is repeatedly visible for learning; no final-test claim is made.</p></details>`,($,root)=>{
const media=matchMedia('(prefers-reduced-motion: reduce)');let raf=0,playing=false,visible=false,last=0,clock=0;
function update(){const k=+$('#k').value,x=+$('#knn-query').value,prediction=M.knn(M.training,x,k),near=M.training.map((r,i)=>({r,i,d:Math.abs(r[0]-x)})).sort((a,b)=>a.d-b.d||a.i-b.i).slice(0,k),px=65+x/12*525,py=280-prediction/50*230;
$('#k-value').textContent=k;$('#knn-query-value').textContent=f(x,1);
const rays=near.map(({r})=>`<line class="neighbor-ray" x1="${65+r[0]/12*525}" y1="${280-r[1]/50*230}" x2="${px}" y2="${py}" stroke="var(--mint)" stroke-width="1.5" opacity=".65"/><circle cx="${65+r[0]/12*525}" cy="${280-r[1]/50*230}" r="7" fill="none" stroke="var(--mint)" stroke-width="2"/>`).join('');
$('#knn-chart').innerHTML=chartFrame(scatter(M.training,12,50)+scatter(M.validation,12,50,'validation')+curve(x=>M.knn(M.training,x,k),12,50)+rays+`<line x1="${px}" y1="280" x2="${px}" y2="${py}" stroke="var(--mint)" stroke-dasharray="4 4"/><circle cx="${px}" cy="${py}" r="8" fill="var(--bg)" stroke="var(--mint)" stroke-width="3"/><text class="label" x="${Math.min(515,Math.max(115,px))}" y="${py-16}" text-anchor="middle">${f(prediction,2)} min</text>`,'Distance (km)','Duration (min)');
$('#knn-chart svg').setAttribute('aria-label',`New trip ${f(x,1)} km. ${k} nearest training trips predict ${f(prediction,2)} minutes.`);
$('#knn-working').textContent=`(${near.map(n=>n.r[1]).join(' + ')}) / ${k} = ${f(prediction,2)} min`;
$('#knn-metrics').innerHTML=`<div class="metrics"><div><small>Training MAE</small><strong>${f(M.mae(M.training.map(r=>r[1]),M.training.map(r=>M.knn(M.training,r[0],k))))}</strong><small>minutes</small></div><div><small>Validation MAE</small><strong>${f(M.mae(M.validation.map(r=>r[1]),M.validation.map(r=>M.knn(M.training,r[0],k))))}</strong><small>minutes</small></div></div>`;
}
function stop(){playing=false;cancelAnimationFrame(raf);last=0;$('#knn-sweep').textContent='Move the new trip';}
function frame(now){if(!playing||!visible||document.hidden||media.matches){stop();return;}if(last)clock+=Math.min(80,now-last);last=now;$('#knn-query').value=(6.5+5.5*Math.sin(clock/2400)).toFixed(1);update();raf=requestAnimationFrame(frame);}
$('#knn-sweep').onclick=()=>{if(playing){stop();return;}playing=true;clock=Math.asin((+$('#knn-query').value-6.5)/5.5)*2400;$('#knn-sweep').textContent='Pause';raf=requestAnimationFrame(frame);};
$('#k').oninput=()=>{stop();update();};$('#knn-query').oninput=()=>{stop();update();};$('#reset-knn').onclick=()=>{stop();$('#k').value=3;$('#knn-query').value=6.5;update();};
const io=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(!visible)stop();},{threshold:.1});io.observe(root);const reduced=()=>{stop();$('#knn-sweep').disabled=media.matches;};media.addEventListener('change',reduced);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});addEventListener('pagehide',()=>{stop();io.disconnect();},{once:true});reduced();update();});
add('catalogue',3,'Learn from answers.<br><em>Or look for structure.</em>','Two learning settings in this catalogue. Choose a family to see how it works.',()=>`
${ModelVisuals.miniControls()}<div class="family-map">
<section class="family-supervised"><p class="eyebrow">KNOWN TRAINING ANSWERS</p><h3>Supervised learning</h3><p>Learn from inputs and known targets. Predict a quantity or a category for a new case.</p><div class="family-previews"><div><h4>Regression · a quantity</h4>${ModelVisuals.mini('quantity')}</div><div><h4>Classification · a category</h4>${ModelVisuals.mini('category')}</div></div><div class="family-links">${CATALOG.filter(m=>m.id!=='kmeans').map(m=>`<a href="#${m.id}-visual" title="${m.idea}"><strong>${m.name}</strong><small>${m.id==='linear'?'Regression':m.id==='logistic'?'Classification':'Regression and classification'}</small></a>`).join('')}</div></section>
<section class="family-unsupervised"><p class="eyebrow">NO KNOWN GROUP LABELS</p><h3>Unsupervised learning</h3><p>Look for structure in the inputs. Here, form groups of similar cases.</p><div class="family-previews"><div><h4>Clustering · groups</h4>${ModelVisuals.mini('groups')}</div></div><div class="family-links">${CATALOG.filter(m=>m.id==='kmeans').map(m=>`<a href="#${m.id}-visual"><strong>${m.name}</strong><small>Distance-based groups</small></a>`).join('')}</div><p class="small">Group numbers have no verified meaning on their own.</p></section></div>
${qa('Where should we start?','Start with the task and a baseline. You do not need to use all seven methods. A model in this manual is not automatically a requirement for an assessment. K-means has no known group label to learn; it explores distance-based groups.')}`,($,root)=>ModelVisuals.mountMini(root));
function manual(m){return `<details class="manual"><summary>Full reference · preparation, settings, evaluation and limits</summary><div class="grid">${panel('When to consider it',`<p>${m.good}</p>`)}${panel('When it can fail',`<p>${m.bad}</p>`)}</div><h3>Prepare the data</h3><p>${m.prep}</p><h3>Learned parameters</h3><p>${m.learned}</p><h3>Settings you choose</h3>${table(['Setting','Meaning and direction of change'],m.hyper)}<h3>Evaluate against a reference</h3><p>${m.evaluation}</p><h3>Variants and boundaries</h3><p>${m.variants}</p>${source(m.ref,m.refName)}${m.ref2?source(m.ref2,'XGBoost · parameters'):''}</details>`;}
CATALOG.forEach(m=>{const visual=ModelVisuals.specs[m.id];add(m.id+'-visual',3,m.name,visual.subtitle,()=>ModelVisuals.html(m.id),($,root)=>ModelVisuals.mount(m.id,root));add(m.id,3,m.name,`${m.tag} · ${m.idea}`,()=>`
<div class="scene-tag"><span class="pill">${m.question}</span><a class="small" href="#${m.id}-visual">Watch the model diagram ↗</a><a class="small" href="#catalogue">All seven models ↑</a></div><div class="grid wide">${panel('Input → learning → output',`<ol>${m.io.map(s=>`<li>${s}</li>`).join('')}</ol><p class="small">${m.good}</p>`)}${panel('A worked example',`<p>${m.example}</p>`)}</div>
<div style="margin-top:20px">${m.id==='linear'?'<div class="toolbar"><label for="area">Home area (m²) <input id="area" type="range" min="40" max="80" value="65"><output id="area-value"></output></label><button id="linear-reset">Reset</button><span id="linear-prediction" class="formula"></span></div><div id="linear-chart"></div>':m.id==='logistic'?'<div class="toolbar"><label for="days">Waiting days <input id="days" type="range" min="0" max="30" value="10"><output id="days-value"></output></label><button id="logistic-reset">Reset</button></div><div id="logistic-view"></div><p class="small">Live calculation from an invented fixed rule. Coefficients stay −2 and 0.2; no model is fitted here. <a href="#classification">Explore the decision threshold →</a></p>':m.id==='knn'?'<a href="#complexity">Change k and compare new cases →</a>':m.id==='tree'?'<div class="flow"><div><b>Waiting days ≤ 7?</b><span>One illustrative split</span></div><div><b>Yes → left leaf</b><span>1 / 5 missed → p = 0.20</span></div><div><b>No → right leaf</b><span>4 / 5 missed → p = 0.80</span></div></div>':m.id==='forest'?'<a href="#ensembles">Compare averaging and sequential corrections →</a>':m.id==='boost'?'<a href="#ensembles">See the sequence of corrections →</a>':'<a href="#clusters">Change K, scale and starting centres →</a>'}</div>
${manual(m)}${qa(m.check,m.answer)}`,($,root)=>{if(m.id==='linear'){const rows=[[40,120],[50,140],[60,160],[70,180],[80,200]],fit=M.linear(rows);function update(){const x=+$('#area').value;$('#area-value').textContent=x;$('#linear-prediction').textContent=`$${f(fit.a+fit.b*x,0)}k = 40 + 2 × ${x}`;$('#linear-chart').innerHTML=chartFrame(scatter(rows,100,250)+curve(x=>fit.a+fit.b*x,100,250)+point(65+x/100*525,280-(fit.a+fit.b*x)/250*230,'validation','Selected prediction'),'Area (m²)','Price ($ thousands)',100,250);}$('#area').oninput=update;$('#linear-reset').onclick=()=>{$('#area').value=65;update();};update();}if(m.id==='logistic'){function update(){const d=+$('#days').value,z=-2+.2*d,p=1/(1+Math.exp(-z));$('#days-value').textContent=d;$('#logistic-view').innerHTML=`<div class="grid">${panel('Fixed score → probability',`<p class="formula">z = −2 + 0.2 × ${d} = ${f(z,1)}</p><p class="big">p = ${pct(p)}</p><p>Estimated probability of a missed visit.</p>`)}${panel('Probability → decision',`<p>At threshold 0.50: <b>${p>=.5?'flag':'do not flag'}</b>.</p><p>At threshold 0.80: <b>${p>=.8?'flag':'do not flag'}</b>.</p><p class="small">The same probability can lead to different actions. These thresholds illustrate the rule; they are not recommendations.</p>`)}</div>`;}$('#days').oninput=update;$('#logistic-reset').onclick=()=>{$('#days').value=10;update();};update();}});});
add('ensembles',3,'Many trees.<br><em>Two ways to combine them.</em>','Illustrative outputs for the same delivery. The browser does the arithmetic; it does not train Random Forest or XGBoost.',()=>`
<div class="grid"><section class="panel"><h3>Random Forest · average</h3><p>Different trees estimate the same target. They do not correct each other in a sequence.</p><div class="toolbar"><label for="trees">Trees shown <input id="trees" type="range" min="1" max="5" value="3"><output id="trees-value"></output></label></div><div id="forest-view"></div></section><section class="panel"><h3>Boosting · add corrections</h3><p>Start at 20 minutes. Add one correction at a time. Fixed illustrative corrections: +10, −2, +4.</p><div class="toolbar"><label for="rounds">Rounds <input id="rounds" type="range" min="0" max="3" value="2"><output id="rounds-value"></output></label><label for="rate">Learning rate <select id="rate"><option value="0.1">0.1</option><option value="0.3" selected>0.3</option><option value="1">1.0</option></select></label></div><div id="boost-view"></div></section></div><button id="ensemble-reset">Reset both examples</button>
${note('In real boosting, changing the learning rate can change the later trees because they are trained against a different current ensemble. Here the correction values stay fixed to isolate the arithmetic.')}
${qa('Does this example show which ensemble is more accurate?','No. It shows how outputs combine. We would need observed answers and a fair validation procedure to compare accuracy or error.')}`,($,root)=>{function update(){const n=+$('#trees').value,r=+$('#rounds').value,lr=+$('#rate').value,trees=[22,28,25,24,26].slice(0,n),cor=[10,-2,4].slice(0,r);$('#trees-value').textContent=n;$('#rounds-value').textContent=r;$('#forest-view').innerHTML=`<p>${trees.join(' + ')} divided by ${n}</p><p class="big">${f(M.mean(trees),1)} min</p><p class="small">More trees stabilize an average; they do not automatically overfit.</p>`;$('#boost-view').innerHTML=`<p>20 ${cor.map(c=>`${c<0?'−':'+'} ${f(lr*Math.abs(c),1)}`).join(' ')}</p><p class="big">${f(20+lr*cor.reduce((s,v)=>s+v,0),1)} min</p><p class="small">More rounds can improve or worsen validation loss.</p>`;}['trees','rounds','rate'].forEach(id=>$('#'+id).oninput=update);$('#ensemble-reset').onclick=()=>{$('#trees').value=3;$('#rounds').value=2;$('#rate').value=.3;update();};update();});
add('clusters',3,'Groups depend on <em>distance.</em>','Twelve synthetic customers from one invented month. x = items bought; y = monthly spend in dollars. No target labels.',()=>`
<div class="toolbar"><label for="clusters-k">Groups K <select id="clusters-k"><option>1</option><option>2</option><option selected>3</option><option>4</option></select></label><label for="scale"><input id="scale" type="checkbox" checked> Standardize both features</label><label for="seed">Starting centres <select id="seed"><option value="0">Set A</option><option value="1">Set B</option></select></label><button id="cluster-reset">Reset</button>${badge('Live Lloyd iterations')}</div>
<div class="grid wide"><section class="panel"><div id="cluster-chart"></div><p class="small">Numbers identify assigned groups; crosses show centres. Axes always use original units, even when distances use standardized values.</p></section><section class="panel"><h3>What changes?</h3><p>The browser refits assignments and group means. Standardization subtracts each feature’s mean and divides by its standard deviation. This gives equal spread for this exploratory fit.</p><div id="cluster-values"></div><p class="small">Inertia is a sum of squared distances in the selected feature space. Do not compare its numeric value across different scaling choices.</p></section></div>
${qa('Do group 1 and group 2 have the same meaning after every change?','No. IDs are arbitrary, and membership can change. Describe a group from its profile; do not treat its number as an ordered score or a true class.')}
<details><summary>Read the data and limits</summary>${table(['Customer','Items / month','Spend ($ / month)'],M.shops.map((r,i)=>[i+1,...r]))}<p>Set A starts at customers 1, 5, 9, 12; set B at 3, 8, 11, 1, taking the first K. One run, maximum 100 iterations; stop when centre movement is negligible. Empty groups retain their previous centre. This demonstration is not k-means++ and does not select the best K.</p><p>A silhouette score needs at least two groups and fewer groups than rows. Assess stability and context even when that score is high.</p></details>`,($,root)=>{function update(){const k=+$('#clusters-k').value,scaled=$('#scale').checked,r=M.kmeans(k,scaled,+$('#seed').value),colors=['var(--plot-mint)','var(--plot-amber)','var(--plot-cyan)','var(--plot-pink)'];let points=M.shops.map((p,i)=>`<circle cx="${65+p[0]/10*525}" cy="${280-p[1]/100*230}" r="10" fill="${colors[r.labels[i]]}"/><text x="${65+p[0]/10*525}" y="${285-p[1]/100*230}" text-anchor="middle" style="fill:var(--bg);font-size:12px">${r.labels[i]+1}</text>`).join('');points+=r.centers.map(c=>{const x=65+c[0]/10*525,y=280-c[1]/100*230;return `<path class="centroid" d="M${x-7},${y-7} l14,14 M${x-7},${y+7} l14,-14"/>`;}).join('');$('#cluster-chart').innerHTML=chartFrame(points,'Items / month','Spend ($ / month)',10,100);$('#cluster-values').innerHTML=`<p class="big">${f(r.inertia)}<small class="small"> inertia</small></p><p class="small">${r.iterations} iterations · ${scaled?'standardized':'raw'} distances</p>${table(['Group','Rows'],r.centers.map((_,i)=>[i+1,r.labels.filter(x=>x===i).length]))}`;}['clusters-k','scale','seed'].forEach(id=>$('#'+id).onchange=update);$('#cluster-reset').onclick=()=>{$('#clusters-k').value=3;$('#scale').checked=true;$('#seed').value=0;update();};update();});
add('regression-metrics',4,'How large are <em>the errors?</em>','Three synthetic validation deliveries. Observed durations: 20, 30 and 40 minutes. Predictions were fixed before checking these answers.',()=>`
<div class="toolbar"><label for="prediction-set">Prediction rule <select id="prediction-set"><option value="model">Candidate: 22, 28, 35</option><option value="baseline">Training mean: 28, 28, 28</option><option value="outlier">One large error: 20, 30, 55</option></select></label><button id="metric-reset">Reset</button>${badge('Live calculation from illustrative predictions')}</div><div class="grid"><section class="panel"><div id="error-table"></div></section><section class="panel"><h3>Same target units</h3><p>Residual = observed − predicted.</p><p class="formula">MAE = mean of |residual|</p><p class="formula">RMSE = √mean of residual²</p><div id="reg-metrics"></div><p class="small result">The baseline mean of 28 comes from separate illustrative training durations 20, 28 and 36 min. MAE weights each absolute error directly. RMSE gives larger errors more influence. Both are in minutes; the squared errors are in min².</p></section></div>
${qa('Why not choose the metric after seeing which one our favourite model wins?','That would bias the comparison. Define the primary metric from the cost of errors first. A lower score here is only a result on three invented cases, not evidence about a real transport service.')}`,($,root)=>{function update(){const y=[20,30,40],p={model:[22,28,35],baseline:[28,28,28],outlier:[20,30,55]}[$('#prediction-set').value];$('#error-table').innerHTML=table(['Actual min','Predicted min','Residual min','|Error| min','Error² min²'],y.map((v,i)=>[v,p[i],v-p[i],Math.abs(v-p[i]),(v-p[i])**2]));$('#reg-metrics').innerHTML=`<div class="metrics"><div><small>MAE</small><strong>${f(M.mae(y,p))} min</strong></div><div><small>RMSE</small><strong>${f(M.rmse(y,p))} min</strong></div></div>`;}$('#prediction-set').onchange=update;$('#metric-reset').onclick=()=>{$('#prediction-set').value='model';update();};update();});
add('classification',4,'One threshold.<br><em>Four counts.</em>','Ten synthetic appointments. Positive means “missed visit”. Probabilities are invented and fixed; answers are known for validation.',()=>`
<div class="toolbar"><label for="threshold">Flag if p ≥ <input id="threshold" type="range" min="0" max="1" step="0.01" value="0.50"><output id="threshold-value"></output></label><button id="threshold-reset">Reset</button>${badge('Live counts and metrics')}</div>
<div class="grid wide"><section class="panel"><h3>Rows: actual · columns: predicted</h3><p class="small">TP = correct flags · FP = false alerts · FN = missed positives · TN = correct negatives.</p><div id="confusion"></div><div id="class-metrics" class="result"></div></section><section class="panel"><h3>Denominators matter</h3><p><b>Precision:</b> among flagged cases, how many really missed?</p><p><b>Recall / sensitivity:</b> among actual missed visits, how many did we flag?</p><p><b>F1:</b> balances precision and recall. It does not include true negatives.</p><p><b>Accuracy:</b> all correct decisions divided by all cases.</p></section></div>
<details><summary>All ten cases · probabilities and decisions</summary><div id="classification-rows"></div></details>
${qa('Why can accuracy be misleading here?','Predicting “not missed” for everyone is 70% accurate because 7 of 10 visits are not missed. Recall is then zero: it finds none of the three missed visits. With no positive predictions, precision is undefined; the display says so instead of hiding the denominator.')}
<details><summary>Metric definitions and use</summary><p>TP: true positives; FP: false positives; FN: false negatives; TN: true negatives.</p><p>Precision = TP / (TP + FP). Recall = TP / (TP + FN). F1 = 2TP / (2TP + FP + FN). Accuracy = (TP + TN) / N.</p><p>Choose the threshold using validation and the cost of missed cases versus false alerts. For multiclass tasks, specify per-class results and how scores are averaged. These synthetic bookings are not a medical decision aid.</p></details>`,($,root)=>{function update(){const t=+$('#threshold').value,c=M.confusion(M.clinic.prob,M.clinic.y,t);$('#threshold-value').textContent=f(t);$('#confusion').innerHTML=table(['Actual ↓ / predicted →','Flag +','Do not flag −'],[['Missed +',`TP = ${c.tp}`,`FN = ${c.fn}`],['Not missed −',`FP = ${c.fp}`,`TN = ${c.tn}`]]);$('#class-metrics').innerHTML=`<div class="metrics">${['precision','recall','f1','accuracy'].map(k=>`<div><small>${k==='f1'?'F1':k}</small><strong>${pct(c[k])}</strong></div>`).join('')}</div>`;$('#classification-rows').innerHTML=table(['Case','p(missed)','Actual missed','Flag'],M.clinic.prob.map((p,i)=>[i+1,f(p),M.clinic.y[i]?'yes':'no',p>=t?'yes':'no']));}$('#threshold').oninput=update;$('#threshold-reset').onclick=()=>{$('#threshold').value=.5;update();};update();});
add('fair-comparison',4,'Compare the <em>whole procedure.</em>','Same relevant partitions. Same primary metric. Preparation learned inside each training fold.',()=>`
<div class="flow"><div><b>Training fold</b><span>Fit imputer → encoder → scaler → model.</span></div><div><b>Validation fold</b><span>Apply saved preparation. Predict. Measure error.</span></div><div><b>Repeat folds</b><span>Start with unfitted preparation each time. Compare configurations.</span></div><div><b>Final test</b><span>Evaluate the selected, refitted procedure once. Do not use it to choose.</span></div></div>
<div class="grid">${panel('A tiny mean difference is not proof',`${table(['Illustrative MAE (min)','Fold 1','Fold 2','Fold 3','Mean'],[['A',3,6,3,4],['B',4,3.8,4.1,3.97]])}<p class="small">B has a slightly lower mean, but does not win every fold. These invented scores do not support a statistical superiority claim. Consider variation and practical value.</p>`)}${panel('Fit the design to the use',`<p>Future dates need time-aware splits. Repeated people, stores or sites may need group-aware splits. Random row splits can leak shared context.</p><p>Also compare training time, prediction time, simplicity, interpretation and useful error reduction.</p>`)}</div>
${qa('Can we scale all development rows once, then run CV on the scaled matrix?','No, if scaling estimates use all those rows. Each validation fold has influenced preparation. Put fitted transformations inside the procedure refit on each training fold. This includes feature selection and imputation.')}
${source('https://scikit-learn.org/stable/common_pitfalls.html','scikit-learn · leakage and pipelines')}`);
add('lazypredict',5,'LazyPredict:<br><em>a first comparison.</em>','LazyRegressor compares numeric-target candidates. LazyClassifier compares classification candidates.',()=>`
<div class="flow"><div><b>Receives</b><span>Training inputs/answers and a separate evaluation set.</span></div><div><b>Runs candidates</b><span>Fits a set of estimators using the library’s configurations and preparation.</span></div><div><b>Returns</b><span>A table of scores and times; optional predictions.</span></div></div>
<div class="grid wide"><section class="panel"><h3>Read a ranking carefully</h3>${badge('Invented teaching table · NOT a LazyPredict run')}${table(['Candidate','RMSE (min) ↓','Time (s) ↓','Status'],[['Tree ensemble','4.10','1.80','Scored'],['Linear model','4.15','0.02','Scored'],['Neighbour model','4.60','0.05','Scored'],['Candidate D','—','—','Failed: inspect error']])}<p class="small">The data context is a fictional delivery task. Scores and times are invented to practise reading. No dataset split, software version or measured benchmark is claimed.</p></section>${panel('What the table does not prove',`<p>A ranking belongs to one dataset, split, metric, version and candidate configuration.</p><p>A failed model has no valid score. Review warnings, compatibility and whether the candidate fits the task.</p><p>Comparing defaults is not exhaustive tuning. “Many models” does not mean all models run literally in parallel.</p>`)}</div>
${qa('The first model wins RMSE by 0.05 minutes. Must we choose it?','No. Check whether the gain repeats under valid evaluation and matters in use. The simpler, faster model can be a reasonable candidate. The example is illustrative, so it supports no empirical winner.')}
${source('https://lazypredict.readthedocs.io/en/latest/usage.html','LazyPredict · usage')}`);
add('lazy-code',5,'A set called “test” can still<br><em>be validation.</em>','If you use its scores to choose a model, it plays a validation role—even if an API calls it X_test.',()=>`
<div class="grid wide"><section><pre><code># Reference only: not executed by this HTML.
from sklearn.datasets import load_diabetes
from sklearn.model_selection import train_test_split
from lazypredict.Supervised import LazyRegressor

X, y = load_diabetes(return_X_y=True, scaled=False)
# Example split for this demonstration, not a universal rule.
X_dev, X_final, y_dev, y_final = train_test_split(
    X, y, test_size=0.20, random_state=42)
X_train, X_val, y_train, y_val = train_test_split(
    X_dev, y_dev, test_size=0.25, random_state=42)

runner = LazyRegressor(ignore_warnings=False)
scores, predictions = runner.fit(
    X_train, X_val, y_train, y_val)
print(scores)
# X_final and y_final have not been scored here.</code></pre></section>${panel('What happens next?',`<p>Use the table to shortlist candidates. Audit preprocessing, warnings and version behaviour. Rebuild promising candidates in explicit pipelines for cross-validation.</p><p>Lock the choice, then refit on development data and evaluate once on the held-out final test.</p><p class="small">This reference uses scikit-learn’s diabetes example: 442 patients; target is a quantitative disease-progression measure, not a diagnosis. Predictive use is only illustrative here.</p>`)}</div>
${note('The old LazyPredict regression documentation includes a removed scikit-learn dataset. This reference avoids that example. It is a code-reading aid, not a verified installation tutorial.')}
<details><summary>Classification counterpart</summary><pre><code>from lazypredict.Supervised import LazyClassifier
runner = LazyClassifier(ignore_warnings=False)
scores, predictions = runner.fit(
    X_train, X_val, y_train, y_val)
# Here y must contain class labels, not the diabetes target.
# Use an appropriate stratified, grouped or temporal split.</code></pre><p>Inspect which metrics are returned and what they mean for your labels. Do not mix regression and classification rankings.</p></details>
${source('https://scikit-learn.org/stable/modules/generated/sklearn.datasets.load_diabetes.html','scikit-learn · diabetes example')}`);
add('search',6,'Search settings.<br><em>Keep validation honest.</em>','Live 3-fold CV on the 12 synthetic delivery training rows. The six demonstration validation rows are not used here.',()=>`
<div class="toolbar"><label for="search-mode">Search design <select id="search-mode"><option value="grid">Grid: all 8 combinations</option><option value="random">Random: 4 draws, seed 42</option></select></label><button id="search-reset">Reset</button>${badge('Live kNN fits and scores')}</div><div class="grid wide"><section class="panel"><div id="search-results"></div></section><section class="panel"><h3>What is a search?</h3><p>Grid search checks every listed combination. Random search samples combinations from defined choices or distributions.</p><p>Here: k ∈ {1, 3, 5, 7}; weighting ∈ {uniform, distance}. A reproducible pseudo-random draw (seed 42) selects four combinations without replacement.</p><div id="search-cost"></div><p class="small result">More tries cost more and can overfit our decisions to validation. A larger search does not guarantee a better future result.</p></section></div>
${qa('Does the smallest CV mean prove this is the best model family?','No. It is the lowest mean among the configurations tried under this small design. It does not compare untried families, estimate population representativeness or replace a final test.')}
<details><summary>Fold design and preprocessing boundary</summary><p>Rows are assigned cyclically to three folds: indices 0,3,6,9; 1,4,7,10; 2,5,8,11. Each fit uses eight rows and validates on four. The one feature is distance in km, so this example has no fitted scaling or imputation. Ties use training order.</p><p>For several features, put all learned preparation inside each fit. In real delivery data, repeated routes or future-time deployment may require another split. Do not treat this tiny synthetic demonstration as a recommended validation design.</p></details>`,($,root)=>{function update(){const combinations=[1,3,5,7].flatMap(k=>[false,true].map(w=>({k,w,scores:M.cv(k,w)})));let seed=42;const sample=[0,1,2,3,4,5,6,7];for(let i=7;i>0;i--){seed=(Math.imul(1664525,seed)+1013904223)>>>0;const j=Math.floor(seed/4294967296*(i+1));[sample[i],sample[j]]=[sample[j],sample[i]];}const chosen=$('#search-mode').value==='grid'?combinations:sample.slice(0,4).map(i=>combinations[i]);chosen.sort((a,b)=>M.mean(a.scores)-M.mean(b.scores));$('#search-results').innerHTML=table(['k','Weights','Fold 1','Fold 2','Fold 3','Mean MAE min'],chosen.map(c=>[c.k,c.w?'distance':'uniform',...c.scores.map(v=>f(v)),f(M.mean(c.scores))]));$('#search-cost').innerHTML=`<p class="big">${chosen.length*3} fits</p><p>${chosen.length} configurations × 3 folds, before final refit.</p><p class="small">Top here: k=${chosen[0].k}, ${chosen[0].w?'distance':'uniform'} weights.</p>`;}$('#search-mode').onchange=update;$('#search-reset').onclick=()=>{$('#search-mode').value='grid';update();};update();});
add('automl',6,'Automation expands the search.<br><em>It does not define the problem.</em>','auto-sklearn is a conceptual example of automated selection and configuration.',()=>`
<div class="grid">${panel('What auto-sklearn can automate','<p>Search among algorithms, preprocessing choices and hyperparameters within time/resource budgets. It can combine fitted models into an ensemble.</p><p>The choices are still constrained by the supported search space and evaluation procedure.</p>')}${panel('What we must decide','<p>Target and unit. Available inputs. Population. Leakage boundary. Relevant split. Metric and error costs. Resource limits and legitimate use.</p><p>Automation cannot infer those decisions reliably from a CSV file alone.</p>')}</div>
<div class="flow"><div><b>Catalogue</b><span>Propose candidates.</span></div><div><b>Comparison</b><span>Measure candidates.</span></div><div><b>Search</b><span>Adjust configurations.</span></div><div><b>Final test</b><span>Check the locked choice.</span></div></div>
${note('Environment note: the auto-sklearn documentation does not support native Windows execution. Linux-based alternatives require their own setup and checks. No installation is needed or performed for this HTML; no compatible local environment is promised.')}
${qa('Is LazyPredict a replacement for all hyperparameter search?','No. It provides an initial comparison. auto-sklearn searches a broader pipeline space. Neither removes the need for valid data, validation and a reserved test.')}
${source('https://automl.github.io/auto-sklearn/master/manual.html','auto-sklearn · manual')}${source('https://automl.github.io/auto-sklearn/master/installation.html','auto-sklearn · installation and platform limits')}`);
add('shap-context',7,'Why did the model<br><em>predict this value?</em>','SHAP allocates a model prediction relative to a reference across input features. It does not tune the model.',()=>`
<div class="grid wide">${panel('A small, reproducible housing model',`<p>Nine synthetic homes. Inputs: area (m²) and distance to transit (km). Target: price in thousands of dollars.</p><p>The browser fits ordinary least squares to all nine rows. The data were deliberately generated from a perfect additive rule:</p><p class="formula">price = 40 + 2 × area − 3 × distance</p><p class="small">No noise and no performance claim. This fitted model is used only to teach exact attribution arithmetic.</p>`)}${panel('Two different references',`<p><b>Performance baseline:</b> a simple model used to compare prediction error.</p><p><b>SHAP reference value:</b> the expected output of the model under the selected background data.</p><p>They can have the same numeric value by coincidence. Their roles are different.</p>`)}</div>
${table(['Area m²','Transit km','Price $k'],M.housing)}
${qa('Can SHAP tell us which hyperparameters to choose?','No. Search and validation choose configurations. SHAP explains a fitted prediction. A plausible explanation does not prove that the prediction is accurate, fair or causally valid.')}`);
add('shap',7,'From a reference<br><em>to one prediction.</em>','Exact interventional SHAP for the fitted additive linear model. Background: the nine synthetic homes from the previous scene.',()=>`
<div class="toolbar"><label for="shap-case">Home <select id="shap-case"><option value="0">A: 80 m², 2 km</option><option value="1">B: 40 m², 8 km</option><option value="2">C: 60 m², 2 km</option></select></label><button id="shap-reset">Reset</button>${badge('Live exact attribution')}</div><div class="grid wide"><section class="panel"><div id="shap-chart"></div><p class="small">A waterfall adds signed contributions. It does not add errors. Green (+) raises this model output; pink (−) lowers it.</p></section><section class="panel"><h3>Everything is in $ thousands</h3><div id="shap-values"></div><p class="small result">Here, contribution = coefficient × (case value − background mean). This formula is exact for an additive linear model with interventional feature masking; it is not a universal formula for all models.</p></section></div>
${qa('Does the positive area contribution mean that an extension will cause this price gain?','No. It allocates the fitted model output under this reference. It does not identify the causal effect of a building intervention. The training data here were invented for arithmetic.')}
<details><summary>Why these are exact SHAP values</summary><p>Background means: 60 m² and 5 km. The fitted coefficients are 2 $k/m² and −3 $k/km; intercept is 40 $k. The background expected output is 145 $k.</p><p>For any coalition of known features, replace the missing features with values from the nine background rows and average predictions. This model is additive, so each feature has the same marginal contribution regardless of order. Averaging the two possible feature orders gives the displayed values exactly.</p><p>We compute this formula locally; we do not run the Python SHAP package. A separate QA check enumerates both feature orders and compares the result. Correlation-aware attribution or another background can allocate credit differently.</p></details>${source('https://shap.readthedocs.io/en/latest/generated/shap.LinearExplainer.html','SHAP · linear model explanation')}`,($,root)=>{function update(){const x=[[80,2],[40,8],[60,2]][+$('#shap-case').value],r=M.shap(x),ys=[r.base,r.base+r.values[0],r.prediction],X=[95,225,355,485],yy=v=>285-v/220*240;let drawing='';for(let v=0;v<=200;v+=50)drawing+=`<line class="gridline" x1="50" x2="600" y1="${yy(v)}" y2="${yy(v)}"/><text x="42" y="${yy(v)+5}" text-anchor="end">${v}</text>`;const vals=[r.base,...r.values,r.prediction],starts=[0,r.base,ys[1],0],ends=[r.base,ys[1],r.prediction,r.prediction];vals.forEach((v,i)=>{drawing+=`<rect x="${X[i]}" y="${yy(Math.max(starts[i],ends[i]))}" width="70" height="${Math.max(2,Math.abs(yy(starts[i])-yy(ends[i])))}" fill="${i===0||i===3?'var(--plot-cyan)':v>=0?'var(--plot-mint)':'var(--plot-pink)'}"/><text class="water-label" x="${X[i]+35}" y="${yy(Math.max(starts[i],ends[i]))-12}" text-anchor="middle">${i===1||i===2?(v>=0?'+':'−'):''}${f(Math.abs(v),0)}</text><text x="${X[i]+35}" y="310" text-anchor="middle">${['Reference','Area','Transit','Prediction'][i]}</text>`;if(i<3)drawing+=`<line x1="${X[i]+70}" x2="${X[i+1]}" y1="${yy(ends[i])}" y2="${yy(ends[i])}" stroke="var(--muted)" stroke-dasharray="4 4"/>`;});$('#shap-chart').innerHTML=`<svg class="chart" viewBox="0 0 640 350" role="img" aria-label="SHAP waterfall: reference ${r.base}, contributions ${r.values.join(', ')}, prediction ${r.prediction}, all in thousands of dollars"><text class="label" x="50" y="20">Model output ($ thousands)</text>${drawing}</svg>`;$('#shap-values').innerHTML=`<p>Area: 2 × (${x[0]} − 60) = <b>${f(r.values[0],0)}</b></p><p>Transit: −3 × (${x[1]} − 5) = <b>${f(r.values[1],0)}</b></p><p class="formula">${f(r.base,0)} ${r.values.map(v=>`${v>=0?'+':'−'} ${f(Math.abs(v),0)}`).join(' ')} = ${f(r.prediction,0)}</p><p class="big">$${f(r.prediction,0)}k</p>`;}$('#shap-case').onchange=update;$('#shap-reset').onclick=()=>{$('#shap-case').value=0;update();};update();});
add('shap-many',7,'One explanation is local.<br><em>Several reveal variation.</em>','Same model, same nine-row background, same output units. Three selected homes are not a population sample.',($,root)=>{
const rows=[[80,2],[40,8],[60,2]].map((x,i)=>{const s=M.shap(x);return [String.fromCharCode(65+i),x[0],x[1],...s.values.map(v=>f(v,0)),f(s.prediction,0)];});return `<div class="grid wide">${panel('Signed contributions for three homes',table(['Home','Area m²','Transit km','Area $k','Transit $k','Prediction $k'],rows)+`<p class="small result">Mean absolute contribution across these three: area = ${(80/3).toFixed(2)} $k; transit = 9 $k. Absolute values show size, but hide direction.</p>`)}${panel('Read the signs and the spread','<p>Area raises home A’s prediction, lowers B’s and contributes zero for C relative to this background mean.</p><p>A summary plot can show how contributions vary across cases. A global mean cannot describe every local prediction.</p>')}</div>
${note('Dependent features can share information. Different background choices and interventional versus conditional explanations can allocate credit differently. Do not interpret a feature ranking as a causal ranking.')}
${qa('Can we compare these dollar contributions with a classifier explanation in log-odds?','Not directly. First identify the explained output scale. A log-odds contribution is not a percentage-point change. Always label the model output, reference and units.')}
${source('https://shap.readthedocs.io/en/latest/example_notebooks/overviews/Be%20careful%20when%20interpreting%20predictive%20models%20in%20search%20of%20causal%20insights.html','SHAP · limits of causal interpretation')}`;});
add('project',8,'Return to <em>your question.</em>','Use this map to explain a candidate. It creates no new submission or assessment requirement.',()=>`
<div class="grid three">${panel('1 · Frame','<p>What is one row? What is the target, if any? What is known at the moment of use?</p>')}${panel('2 · Propose','<p>Which baseline and two plausible candidates fit the task? What pattern might each miss?</p>')}${panel('3 · Prepare','<p>Which inputs need missing-value handling, encoding or scaling? What must be learned from training only?</p>')}${panel('4 · Compare','<p>Which split reflects future use? Which metric reflects the cost of errors? Where is the final test reserved?</p>')}${panel('5 · Interpret','<p>How large and stable is the improvement? Can a simpler model be sufficient? What does the explanation actually show?</p>')}${panel('6 · Limit','<p>Which missing data, selection biases or changes in context could prevent a legitimate use?</p>')}</div>
${note('<b>Connection to W2:</b> preparation leads toward modelling. This class does not add a requirement to train models or report model metrics in W2. Use the separate assignment instructions for its final scope. LazyPredict, XGBoost, AutoML and SHAP are not made compulsory for C2 by appearing here.')}
${qa('Our project has no reliable target label. Should we invent one so that a classifier can run?','No. First resolve whether the target has a meaningful, reliable definition. A descriptive analysis or justified clustering exploration may be useful, but neither creates a valid supervised label.')}`);
add('closing',8,'Choose a reason.<br><em>Then check it.</em>','Use the answers to revise your explanation. No responses are stored.',()=>`
${qa('A forest wins on a random split, but customers repeat across rows. What should we check first?','Check whether the same customer appears in training and validation and whether the intended use concerns new or known customers. A group-aware split may change the result. Do not tune more models before resolving this boundary.')}
${qa('A classifier has 95% accuracy. Is that sufficient?','No. Check class frequencies, the majority baseline, missed positives, false alerts, the threshold and error costs. A rare positive class can be ignored while accuracy stays high.')}
${qa('A K-means solution has a good silhouette score. Can we name the clusters “high risk” and “low risk”?','Not without supporting evidence. Silhouette describes separation under a distance rule. It does not establish risk, truth or a justified action.')}
${qa('SHAP gives a convincing explanation for a wrong prediction. Is there a contradiction?','No. An explanation can accurately describe the model’s behaviour even when its prediction is wrong. Model explanation and prediction validity are different checks.')}
${qa('What remains beyond this lecture?','Apply and verify the full workflow on the project data under the approved assessment instructions. A/B testing still needs separate teaching; the catalogue does not cover it.')}
<p class="result">Before moving on, state one candidate, one preparation step, one fair comparison and one limit. If a reason is unclear, return to its card.</p><a href="#catalogue">Return to the seven model cards ↑</a>`);
add('sources',8,'Keep the lesson.<br><em>Know its boundaries.</em>','One shared offline reference. Optional source links below require an internet connection.',()=>`
<div class="grid">${panel('Open and navigate',`<p>Open this class in a modern browser. Explore and Present share the same examples and preserve your choices during the visit. No Python, account or server is required by the lesson code. The lecture route selects core scenes; All scenes includes extra demonstrations and reference code. This is a suggested route, not a timed agenda.</p><p>Use Explore for continuous reading, Present for one scene, or Sections to choose a topic. Each URL hash names a scene. Full references expand inside model cards. Reset buttons restore each example.</p><p class="small">All state stays in this page. Reload returns controls to their initial values. No student responses or personal data are collected.</p>`)}${panel('What is calculated here?',`<p><b>Live:</b> least squares, kNN predictions/CV, logistic formula, confusion counts, MAE/RMSE, Lloyd K-means and exact linear SHAP.</p><p><b>Illustrative:</b> booking score, tree rule, ensemble outputs, regression predictions, fold-comparison table and LazyPredict table.</p><p><b>Reference code:</b> LazyPredict snippet is not executed. No real LazyPredict, XGBoost or auto-sklearn benchmark is claimed.</p>`)}</div>
<details open><summary>Data, authorship and reuse</summary><p>All distributed numeric data are original synthetic teaching examples created for this lesson. They describe no real people, clinics, shops or property transactions. The housing SHAP data intentionally have no noise. There is no external dataset or external library bundled in the browser files.</p><p>The design follows the course’s “Beyond the Fit” HTML. Explanations and examples are original teaching adaptations. External documentation is linked as technical reference; its code or dataset license is not applied to this lesson’s data by inference.</p><p>The diabetes dataset is mentioned only in unexecuted reference code. Consult its documentation before reuse. No license for that dataset is inferred from scikit-learn’s software license.</p></details>
<details><summary>Technical sources · consulted 16 October 2026</summary><ul>${CATALOG.map(m=>`<li><a target="_blank" rel="noopener" href="${m.ref}">${m.refName}</a></li>`).join('')}<li><a href="https://scikit-learn.org/stable/common_pitfalls.html" target="_blank" rel="noopener">scikit-learn: preparation, pipelines and leakage</a></li><li><a href="https://scikit-learn.org/stable/modules/model_evaluation.html" target="_blank" rel="noopener">scikit-learn: metrics and scoring</a></li><li><a href="https://scikit-learn.org/stable/modules/grid_search.html" target="_blank" rel="noopener">scikit-learn: hyperparameter search</a></li><li><a href="https://lazypredict.readthedocs.io/en/latest/usage.html" target="_blank" rel="noopener">LazyPredict: usage</a></li><li><a href="https://automl.github.io/auto-sklearn/master/manual.html" target="_blank" rel="noopener">auto-sklearn: manual</a></li><li><a href="https://automl.github.io/auto-sklearn/master/installation.html" target="_blank" rel="noopener">auto-sklearn: platform support</a></li><li><a href="https://shap.readthedocs.io/en/latest/generated/shap.LinearExplainer.html" target="_blank" rel="noopener">SHAP: exact linear attributions</a></li><li><a href="https://shap.readthedocs.io/en/latest/example_notebooks/overviews/Be%20careful%20when%20interpreting%20predictive%20models%20in%20search%20of%20causal%20insights.html" target="_blank" rel="noopener">SHAP: causal interpretation limits</a></li></ul><p>Online APIs and defaults can change. Consult the documentation for the version you actually use. This HTML has no runtime dependency on those sites.</p></details>`);

const blockNames=['','From data to a question','Learning and configuration','Model catalogue','Fair comparison','LazyPredict','Search and AutoML','SHAP introduction','Back to the project'];
const extraIds=new Set(['purpose','ensembles','clusters','regression-metrics','lazy-code','shap-many']);
// Mount each scene once. Local selectors bind its controls to its own DOM.
let current=Math.max(0,scenes.findIndex(s=>s.id===location.hash.slice(1))),route='lecture';
let mode=['explore','read','reading','lectura','explorar'].includes(new URLSearchParams(location.search).get('mode')||new URLSearchParams(location.search).get('modo'))?'explore':'present';
const clean=s=>s.replace(/<br>/g,' ').replace(/<[^>]*>/g,'');
const content=$('#content'),sections=[];
scenes.forEach((s,i)=>{const el=document.createElement('section');el.id=s.id;el.className='lesson-scene';el.dataset.scene=s.id;el.tabIndex=-1;el.innerHTML=`<div class="scene-heading"><span class="scene-number">${String(i+1).padStart(2,'0')}</span><div><p class="eyebrow">${blockNames[s.block]}${extraIds.has(s.id)?' · Extra reference':''}</p>${s.id==='start'?'':`<h2>${s.title.replace(/<br>/g,' ')}</h2><p class="lede">${s.subtitle}</p>`}</div></div><div class="scene-body">${s.html()}</div>`;content.append(el);sections.push(el);s.init?.(selector=>el.querySelector(selector),el);});
function routeIndex(delta){for(let i=current+delta;i>=0&&i<scenes.length;i+=delta)if(route==='all'||!extraIds.has(scenes[i].id))return i;return -1;}
function updateNav(){const s=scenes[current];$('#prev').disabled=routeIndex(-1)<0;$('#next').disabled=routeIndex(1)<0;$('#chapter').textContent=(route==='lecture'?'Lecture · ':'All scenes · ')+blockNames[s.block];$('#counter').textContent=`${current+1} / ${scenes.length}`;$('#progress').style.width=`${(current+1)/scenes.length*100}%`;content.dataset.scene=s.id;document.title=clean(s.title)+' · The Model Lab';}
function url(){const u=new URL(location.href);u.searchParams.delete('modo');u.searchParams.set('mode',mode);u.hash=scenes[current].id;try{history.replaceState(null,'',u);}catch{}}
function render(move=false){document.body.dataset.mode=mode;sections.forEach((el,i)=>el.hidden=mode==='present'&&i!==current);document.querySelectorAll('[data-mode-button]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.modeButton===mode)));$('#presentation-nav').hidden=mode!=='present';updateNav();if(move){sections[current].scrollIntoView({block:'start',behavior:'instant'});sections[current].focus({preventScroll:true});}url();}
function selectScene(index,move=true){if(index<0||index>=scenes.length)return;ModelVisuals.pause();current=index;render(move);}
function go(delta){selectScene(routeIndex(delta));}
function setMode(value){if(mode===value)return;ModelVisuals.pause();mode=value;render(true);}
document.querySelectorAll('[data-mode-button]').forEach(b=>b.onclick=()=>setMode(b.dataset.modeButton));
function menu(){const term=$('#scene-search').value.toLowerCase();$('#scene-list').innerHTML=scenes.map((s,i)=>({s,i})).filter(({s})=>(clean(s.title)+' '+s.subtitle+' '+blockNames[s.block]).toLowerCase().includes(term)).map(({s,i})=>`<a href="#${s.id}" ${i===current?'aria-current="page"':''}><small>${String(i+1).padStart(2,'0')} · ${extraIds.has(s.id)?'EXTRA REFERENCE':'LECTURE ROUTE'}</small>${clean(s.title)}</a>`).join('')||'<p>No matching scene.</p>';}
$('#menu').onclick=()=>{ModelVisuals.pause();$('#scene-search').value='';menu();$('#overview').showModal();$('#scene-search').focus();};$('#close-menu').onclick=()=>$('#overview').close();$('#scene-search').oninput=menu;$('#prev').onclick=()=>go(-1);$('#next').onclick=()=>go(1);$('#route').onchange=()=>{route=$('#route').value;updateNav();};
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{}}
$('#full').onclick=fullscreen;
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;const i=scenes.findIndex(s=>s.id===a.hash.slice(1));if(i<0)return;e.preventDefault();if($('#overview').open)$('#overview').close();selectScene(i);});
document.addEventListener('keydown',e=>{if($('#overview').open&&e.key==='Escape'){e.preventDefault();$('#overview').close();return;}if($('#overview').open||e.target.closest('input,select,textarea,button,summary,a,[contenteditable="true"]')||e.ctrlKey||e.altKey||e.metaKey||mode!=='present')return;if(e.key==='ArrowRight'){e.preventDefault();go(1);}if(e.key==='ArrowLeft'){e.preventDefault();go(-1);}if(e.key==='Home'){e.preventDefault();selectScene(0);}if(e.key.toLowerCase()==='f')fullscreen();});
function fromUrl(){mode=['explore','read','reading','lectura','explorar'].includes(new URLSearchParams(location.search).get('mode')||new URLSearchParams(location.search).get('modo'))?'explore':'present';const i=scenes.findIndex(s=>s.id===location.hash.slice(1));selectScene(i<0?0:i);}
addEventListener('hashchange',fromUrl);addEventListener('popstate',fromUrl);
let scheduled=false;addEventListener('scroll',()=>{if(mode!=='explore'||scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;const edge=document.querySelector('.lesson-topbar').getBoundingClientRect().bottom+80;let i=0;sections.forEach((s,n)=>{if(s.getBoundingClientRect().top<=edge)i=n;});if(i!==current){current=i;updateNav();url();}});},{passive:true});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)ModelVisuals.pauseModel(e.target.dataset.model);}),{threshold:0.05});document.querySelectorAll('.model-cover').forEach(el=>observer.observe(el));
document.addEventListener('themechange',()=>ModelVisuals.pause());addEventListener('pagehide',()=>ModelVisuals.pause());
render();if(location.hash)requestAnimationFrame(()=>sections[current].scrollIntoView({block:'start',behavior:'instant'}));
window.Lesson={scenes:scenes.map(s=>({id:s.id,block:s.block,title:clean(s.title)})),render,selectScene,setMode,get mode(){return mode;}};
